// Nach dem Loop: Gesamtzusammenfassung + Detailaufstellung pro Klaviyo-Liste.
// Baut zusaetzlich einen HTML-Report fuer die Summary-Mail.
// WICHTIG: Hier NICHT mehr werfen - der Guard-Fehler wird erst NACH der Mail
// im Node "Guard-Check" geworfen, damit die Summary-Mail immer rausgeht.
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.list); // leere Items ueberspringen

const guarded = rows.filter(r => r.guardTriggered);

// Pro Liste aufschluesseln (addPlanned = hinzugefuegt, removePlanned = entfernt)
const details = rows.map(r => ({
  brand: r.brand,
  list: r.list,
  listId: r.listId,
  listCreated: !!r.listCreated,
  targetEmails: r.targetEmails || 0,
  currentMembers: r.currentMembers || 0,
  added: r.addPlanned || 0,
  removed: r.guardTriggered ? 0 : (r.removePlanned || 0),
  guardTriggered: !!r.guardTriggered,
  dryRun: !!r.dryRun
})).sort((a, b) => (b.added + b.removed) - (a.added + a.removed));

const summary = {
  lists: rows.length,
  created: rows.filter(r => r.listCreated).length,
  added: details.reduce((a, r) => a + r.added, 0),
  removed: details.reduce((a, r) => a + r.removed, 0),
  guarded: guarded.length,
  dryRun: rows.some(r => r.dryRun)
};

const WARN = String.fromCharCode(9888) + String.fromCharCode(65039); // Warn-Emoji
const ranAt = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const td = (v, extra) => '<td style="padding:6px 10px;border:1px solid #e4e7ec;' + (extra || '') + '">' + v + '</td>';
const th = (v, extra) => '<th style="padding:6px 10px;border:1px solid #e4e7ec;' + (extra || '') + '">' + v + '</th>';

// Nur Listen mit tatsaechlichen Aenderungen (oder Guard) in der Tabelle zeigen
const changed = details.filter(d => d.added > 0 || d.removed > 0 || d.guardTriggered);
const shown = changed.length ? changed : details;

const rowsHtml = shown.map(d => {
  const flags = [];
  if (d.listCreated) flags.push('neu angelegt');
  if (d.guardTriggered) flags.push(WARN + ' Entfernen uebersprungen (Sicherheitsnetz)');
  return '<tr>'
    + td(esc(d.list))
    + td('+' + d.added, 'text-align:right;color:#0a7d33;font-weight:600;')
    + td('-' + d.removed, 'text-align:right;color:#b42318;font-weight:600;')
    + td(d.currentMembers, 'text-align:right;')
    + td(esc(flags.join(', ')), 'color:#8a919b;font-size:12px;')
    + '</tr>';
}).join('');

const subject = '[Klaviyo-Sync'
  + (summary.dryRun ? ' | DRY-RUN' : '')
  + (summary.guarded ? ' | ' + WARN + ' Guard' : '')
  + '] +' + summary.added + ' / -' + summary.removed + ' ueber ' + summary.lists + ' Listen';

const guardBanner = summary.guarded
  ? '<p style="padding:10px 14px;background:#fff4ed;border:1px solid #f9c9a8;border-radius:8px;color:#93370d;">'
    + WARN + ' Sicherheitsnetz bei ' + summary.guarded + ' Liste(n) ausgeloest – Entfernen wurde uebersprungen. Details siehe Tabelle.</p>'
  : '';

const LF = String.fromCharCode(10);
const html = [
  '<div style="font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;color:#16191d;">',
  '<h2 style="margin:0 0 4px;">Appstle → Klaviyo Listen-Sync</h2>',
  '<p style="margin:0 0 16px;color:#545b66;">Lauf: ' + esc(ranAt) + ' (Europe/Berlin)'
    + (summary.dryRun ? ' &middot; <strong>DRY-RUN (keine Schreibvorgaenge)</strong>' : '') + '</p>',
  '<table style="border-collapse:collapse;margin-bottom:20px;">',
  '<tr>' + td('Listen gesamt') + td(summary.lists, 'text-align:right;font-weight:600;')
    + td('neu angelegt') + td(summary.created, 'text-align:right;font-weight:600;') + '</tr>',
  '<tr>' + td('Mitglieder hinzugefuegt') + td('+' + summary.added, 'text-align:right;font-weight:600;color:#0a7d33;')
    + td('Mitglieder entfernt') + td('-' + summary.removed, 'text-align:right;font-weight:600;color:#b42318;') + '</tr>',
  '</table>',
  guardBanner,
  '<h3 style="margin:0 0 8px;">' + (changed.length ? 'Geaenderte Listen' : 'Alle Listen (keine Aenderungen)') + '</h3>',
  '<table style="border-collapse:collapse;font-size:13px;">',
  '<thead><tr style="background:#f5f6f8;">'
    + th('Liste', 'text-align:left;') + th('Hinzugefuegt', 'text-align:right;') + th('Entfernt', 'text-align:right;')
    + th('Mitglieder aktuell', 'text-align:right;') + th('Hinweis', 'text-align:left;') + '</tr></thead>',
  '<tbody>' + (rowsHtml || '<tr>' + td('Keine Listen verarbeitet.', 'color:#8a919b;') + '</tr>') + '</tbody>',
  '</table>',
  '</div>'
].join(LF);

return [{ json: { ...summary, ranAt, subject, html, details } }];

// Laeuft NACH der Summary-Mail: bei ausgeloestem Sicherheitsnetz Fehler werfen,
// damit der Error-Workflow benachrichtigt (die Mail ist zu diesem Zeitpunkt bereits versendet).
const s = $json || {};
if (s.guarded > 0) {
  const list = (s.details || [])
    .filter(d => d.guardTriggered)
    .map(d => `${d.list} (${d.removed === 0 ? 'uebersprungen' : d.removed})`)
    .join('; ');
  throw new Error('Klaviyo-Sync: Sicherheitsnetz hat Entfernen uebersprungen bei ' + s.guarded + ' Liste(n): ' + list);
}
return [{ json: s }];

// Alle Vertraege (alle Seiten) dieses Plan x Status -> eindeutige E-Mail-Menge
const ctx = $('Loop Over Items').first().json;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const emails = new Set();
let contracts = 0;
let withoutEmail = 0;
let invalid = 0;

for (const item of $input.all()) {
  const c = item.json;
  // leeres Item (alwaysOutputData bei 0 Treffern) ueberspringen
  if (!c || (c.subscriptionContractId ?? c.id) === undefined) continue;
  contracts++;

  const raw = c.customerEmail;
  if (!raw) { withoutEmail++; continue; }

  const email = String(raw).trim().toLowerCase();
  if (!EMAIL_RE.test(email)) { invalid++; continue; }
  emails.add(email);
}

return [{
  json: {
    ...ctx,
    targetEmails: [...emails],
    contracts,
    withoutEmail,
    invalid
  }
}];

// Wertet die Klaviyo-Listensuche eindeutig zu einem Boolean aus.
// (Ein direkter Zahlenvergleich "data.length > 0" in der IF-Node ist unzuverlaessig,
// da n8n bei 0 als Ergebnis manche numerischen Bedingungen faelschlich als erfuellt behandelt -
// daher hier explizit im Code auswerten statt in der IF-Node vergleichen zu lassen.)
const ctx = $('Ziel-E-Mails sammeln').first().json;
const body = $json || {};
const matches = Array.isArray(body.data) ? body.data : [];

return [{
  json: {
    ...ctx,
    listExists: matches.length > 0,
    existingListId: matches.length > 0 ? matches[0].id : null
  }
}];

// Wird nach "Liste vorhanden?" (Treffer, $json = Suchergebnis-Kontext von "Suchergebnis auswerten1")
// ODER nach "Klaviyo Liste anlegen" (neu angelegt, $json = rohe Create-Response von POST /api/lists) ausgefuehrt.
const ctx = $('Suchergebnis auswerten1').first().json;

let listId = ctx.existingListId || null;
let listCreated = false;

if (!listId) {
  // Kein Treffer bei der Suche -> dieser Durchlauf kommt aus dem Anlegen-Zweig,
  // $json ist dann direkt die Antwort von POST /api/lists ({ data: { id, ... } })
  const body = $json || {};
  listId = body.data && body.data.id;
  listCreated = true;
}

if (!listId) {
  throw new Error('Klaviyo-Liste konnte nicht ermittelt werden: ' + ctx.listName);
}

return { json: { ...ctx, listId, listCreated } };

// ---- Konfiguration ----
const DRY_RUN = false;            // true = nur berechnen, NICHTS in Klaviyo schreiben
const CHUNK_REMOVE = 1000;       // Klaviyo: max. 1000 Profile pro Remove-Call
const CHUNK_ADD = 5000;          // Klaviyo: max. 10.000 Profile pro Bulk-Import-Job
const GUARD_MIN_REMOVALS = 50;   // Sicherheitsnetz: Entfernen ueberspringen, wenn ...
const GUARD_MAX_SHARE = 0.5;     // ... mehr als 50 % der Liste (und >= 50 Profile) entfernt wuerden
// ---- Ende Konfiguration ----

const ctx = $('Listen-ID festlegen').first().json;
const target = new Set(ctx.targetEmails);

// Aktuelle Listenmitglieder aus allen Seiten: email -> [profileIds]
const current = new Map();
let withoutEmail = 0;
for (const page of $input.all()) {
  const data = (page.json && page.json.data) || [];
  for (const p of data) {
    const email = String((p.attributes && p.attributes.email) || '').trim().toLowerCase();
    if (!email) { withoutEmail++; continue; } // nicht zuordenbar -> nicht anfassen
    if (!current.has(email)) current.set(email, []);
    current.get(email).push(p.id);
  }
}

const toAdd = [...target].filter(e => !current.has(e));
let toRemove = [];
for (const [email, ids] of current) {
  if (!target.has(email)) toRemove.push(...ids);
}

// Sicherheitsnetz gegen Massenentfernung (z.B. bei fehlerhaften/leeren Appstle-Antworten)
const currentCount = current.size;
const removePlanned = toRemove.length;
let guardTriggered = false;
if (removePlanned >= GUARD_MIN_REMOVALS && removePlanned > currentCount * GUARD_MAX_SHARE) {
  guardTriggered = true;
  toRemove = [];
}

const stats = {
  brand: ctx.brand,
  list: ctx.listName,
  listId: ctx.listId,
  listCreated: ctx.listCreated,
  contracts: ctx.contracts,
  targetEmails: target.size,
  currentMembers: currentCount,
  addPlanned: toAdd.length,
  removePlanned,
  guardTriggered,
  dryRun: DRY_RUN
};

const base = { brand: ctx.brand, klaviyoVar: ctx.klaviyoVar, listId: ctx.listId, listName: ctx.listName };
const chunks = (arr, n) => {
  const out = [];
  for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n));
  return out;
};

const items = [];
if (!DRY_RUN) {
  for (const chunk of chunks(toRemove, CHUNK_REMOVE)) items.push({ json: { ...base, op: 'remove', chunk, stats } });
  for (const chunk of chunks(toAdd, CHUNK_ADD)) items.push({ json: { ...base, op: 'add', chunk, stats } });
}
if (items.length === 0) items.push({ json: { ...base, op: 'noop', chunk: [], stats } });

return items;

// Laeuft nach dem Schreiben (oder direkt bei "keine Aenderungen") -> genau 1 Item zurueck in die Schleife
const s = $('Diff berechnen').first().json.stats;
return [{ json: s }];

